/**
 * If inbound is from a company desk that has an open forwarded lead,
 * relay text/image/PDF back to the original customer.
 */
async tryRelayDeskQuote(message, phone, chatId, body) {
  const digits = this.formatPhone(phone);
  if (!digits) return false;

  // Prefer exact forwarded_to match; also accept known desk phones
  let lead = Submissions.findAwaitingQuoteByDeskPhone(digits);
  if (!lead && InternalNumbers.isDeskPhone(digits)) {
    lead = Submissions.findAwaitingQuoteByDeskPhone(digits);
  }
  if (!lead) return false;

  const customerTo = lead.customer_chat_id || lead.customer_phone;
  console.log(
    `[Relay] Desk ${digits} → customer ${lead.customer_phone} (lead #${lead.id})`
  );

  const caption =
    body ||
    (message.hasMedia
      ? `📄 Quotation from ${lead.company || 'your insurer'} for ${lead.customer_name || 'you'}`
      : '');

  try {
    if (message.hasMedia) {
      const media = await message.downloadMedia();
      if (!media) {
        console.warn('[Relay] downloadMedia returned empty');
        if (caption) await this.sendMessage(customerTo, caption, { chatId: lead.customer_chat_id });
      } else {
        await this.sendMedia(customerTo, media, {
          caption: caption || undefined,
          chatId: lead.customer_chat_id,
        });
      }
    } else if (caption) {
      const intro = `📩 *Update from ${lead.company || 'insurer'}*\n\n${caption}`;
      await this.sendMessage(customerTo, intro, { chatId: lead.customer_chat_id });
    } else {
      return false;
    }

    MessageLog.add({
      direction: 'out',
      phone: lead.customer_phone,
      body: `[relayed from desk ${digits}] ${caption || '[media]'}`,
    });
    console.log(`[Relay] Delivered to customer ${lead.customer_phone}`);
    return true;
  } catch (err) {
    console.error('[Relay] Failed to deliver quote to customer:', err.message);
    return true; // still "handled" as desk message — don't run customer triggers
  }
}

async sendMedia(to, media, options = {}) {
  if (!this.client) throw new Error('WhatsApp client is not ready');
  const run = async () => {
    const chatId =
      options.chatId ||
      (String(to).includes('@') ? to : await this.resolveOutboundChatId(to));
    const result = await this.client.sendMessage(chatId, media, {
      caption: options.caption || undefined,
    });
    MessageLog.add({
      direction: 'out',
      phone: this.formatPhone(to) || String(chatId).replace(/@.+$/, ''),
      body: options.caption || '[media]',
    });
    return result;
  };
  const next = this._sendQueue.then(run, run);
  this._sendQueue = next.catch(() => {});
  return next;
}

/**
 * Always-available greeting reply (does not depend on Admin Panel keywords).
 */
async sendGreetingFormLink(phone, opts = {}) {
  const existing = Submissions.findLatestOpen(phone);
  if (existing && existing.status === 'awaiting_confirmation') {
    await this.sendMessage(
      phone,
      Settings.get('already_pending_message') ||
        'You already have a pending request. Reply *Yes* / *No* to confirm.',
      opts
    );
    return true;
  }

  // Prefer visual workflow (includes 3–5s delay)
  if (Workflows.getActive()) {
    const result = await this.engine.handleIncomingMessage({
      phone,
      body: 'hi',
      chatId: opts.chatId,
      replyTo: opts.replyTo,
    });
    if (result?.handled) return true;
  }

  const submission =
    existing && existing.status === 'awaiting_form'
      ? existing
      : Submissions.create({ token: uuidv4(), customer_phone: phone });
  if (opts.chatId) Submissions.setCustomerChatId(submission.token, opts.chatId);

  const formLink = `${this.getBaseUrl()}/form/${submission.token}`;
  const business = Settings.get('business_name', 'SecureLife Insurance');
  const text =
    `Welcome to *${business}*! 👋\n\n` +
    `To get started with your insurance enquiry, please fill out this short form:\n${formLink}\n\n` +
    `Our team will assist you once you submit and confirm your details.`;

  const delay = humanDelayMs();
  console.log(`[WhatsApp] Greeting delay ${delay}ms before form link`);
  await sleep(delay);
  await this.sendMessage(phone, text, opts);
  console.log(`[WhatsApp] Greeting form link sent → ${phone}: ${formLink}`);
  return true;
}

