async legacyHandleMessage(phone, body, opts = {}) {
  const lower = normalizeMsg(body);

  if (['yes', 'y', 'confirm', 'ok', 'okay'].includes(lower)) {
    const pending = Submissions.findPendingConfirmation(phone);
    if (pending) {
      await this.confirmAndForward(pending, opts);
      return true;
    }
  }

  if (['no', 'n', 'cancel'].includes(lower)) {
    const pending = Submissions.findPendingConfirmation(phone);
    if (pending) {
      Submissions.markCancelled(pending.id);
      await this.sendMessage(phone, Settings.get('cancel_message'), opts);
      return true;
    }
  }

  const flow = ChatFlow.findByKeyword(body);
  if (!flow) {
    console.log(`[WhatsApp] No chat-flow keyword match for: "${body}"`);
    return false;
  }

  const existing = Submissions.findLatestOpen(phone);
  if (existing && existing.status === 'awaiting_confirmation') {
    await this.sendMessage(phone, Settings.get('already_pending_message'), opts);
    return true;
  }

  const submission =
    existing && existing.status === 'awaiting_form'
      ? existing
      : Submissions.create({ token: uuidv4(), customer_phone: phone });

  const formLink = `${this.getBaseUrl()}/form/${submission.token}`;
  const text = this.renderTemplate(flow.response_template, {
    business_name: Settings.get('business_name', 'SecureLife Insurance'),
    form_link: formLink,
    phone,
  });
  console.log(`[WhatsApp] Legacy flow reply → ${phone}: form link`);
  await this.sendMessage(phone, text, opts);
  return true;
}

